import { templateText } from './i18n/index.js';
import type { AsamI18n } from '@asam-ui/ui/i18n';
import type { TemplateMessageKey } from './i18n/index.js';
import { readonly, shallowRef } from 'vue';
import type { ResultController, ResultFeedback, ResultHost, ResultInput } from './Types.js';

/** 宿主拥有实际业务副作用、router 和 navigation；这里只管理本次展示。 */
export function createResultController<TInput extends ResultInput>(
	initial: TInput,
	initialHost: ResultHost
): ResultController<TInput> {
	const feedback = shallowRef<ResultFeedback>({ phase: 'idle', message: '' });
	const feedbackKey = shallowRef<TemplateMessageKey>();
	function setFeedback(next: { value: ResultFeedback; key?: TemplateMessageKey }) {
		feedbackKey.value = next.key;
		feedback.value = next.value;
	}
	let input = initial;
	let host = initialHost;
	let epoch = 0;
	let disposed = false;
	let abort: AbortController | undefined;
	function invalidate() {
		epoch++;
		abort?.abort();
		abort = undefined;
	}
	function available() {
		return !disposed && !input.disabled && !input.readonly && feedback.value.phase !== 'busy';
	}
	function replace(next: TInput, nextHost = host) {
		if (disposed) return;
		invalidate();
		input = next;
		host = nextHost;
		setFeedback({ value: { phase: 'idle', message: '' } });
	}
	async function recover() {
		if (
			!available() ||
			!host.recovery ||
			!['failure', 'server-error', 'forbidden'].includes(input.kind)
		)
			return;
		const ticket = ++epoch;
		const own = Object.freeze<ResultInput>({ ...input });
		const service = host.recovery;
		abort = new AbortController();
		const signal = abort.signal;
		setFeedback({
			value: { phase: 'busy', message: '正在读取最新结果…' },
			key: 'app.templates.results.readingTheLatestResult'
		});
		try {
			if (service.operation !== 'read' && service.operation !== 'verify')
				throw new Error('非法恢复动作');
			const result = await service.run({ ...own, signal });
			if (disposed || ticket !== epoch) return;
			// 403 的事实由宿主替换页面输入；一次读回不能在本页伪造解锁。
			if (own.kind === 'forbidden' || result.status === 'denied') {
				setFeedback({
					value: {
						phase: 'denied',
						message: '当前仍无访问权限，请联系资源负责人。'
					},
					key: 'app.templates.results.accessIsStillDeniedContactTheResourceOwner'
				});
			} else if (result.status === 'confirmed') {
				setFeedback({
					value: { phase: 'confirmed', message: '已核实结果，可以继续。' },
					key: 'app.templates.results.theResultHasBeenVerifiedYouCanContinue'
				});
			} else {
				setFeedback({
					value: { phase: 'failed', message: '仍未恢复，请稍后重新核实或返回。' },
					key: 'app.templates.results.stillUnavailableVerifyAgainLaterOrReturn'
				});
			}
		} catch (error) {
			if (!disposed && ticket === epoch) {
				setFeedback({
					value: {
						phase: 'failed',
						message: '本次读取失败，原结果未改变。可重新核实或返回。'
					},
					key: 'app.templates.results.thisReadFailedTheOriginalResultIsUnchangedVerify'
				});
				throw error;
			}
		}
	}
	async function go(intent: 'return' | 'next') {
		if (!available()) return;
		if (
			intent === 'next' &&
			!(
				(input.kind === 'success' && input.confirmed === true) ||
				(['failure', 'server-error'].includes(input.kind) &&
					feedback.value.phase === 'confirmed')
			)
		)
			return;
		const requested = intent === 'return' ? input.returnTarget : input.nextTarget;
		const target =
			requested && host.allows(requested)
				? requested
				: intent === 'return'
					? host.fallback
					: undefined;
		if (!target || !host.allows(target)) {
			setFeedback({
				value: { phase: 'failed', message: '没有可用的导航目标，请联系页面负责人。' },
				key: 'app.templates.results.noNavigationTargetIsAvailableContactThePageOwner'
			});
			return;
		}
		const previousPhase = feedback.value.phase;
		const ticket = ++epoch;
		const own = Object.freeze<ResultInput>({ ...input });
		abort = new AbortController();
		const signal = abort.signal;
		setFeedback({
			value: { phase: 'busy', message: '正在打开目标页面…' },
			key: 'app.templates.results.openingTheTargetPage'
		});
		try {
			const accepted = await host.navigate(target, { ...own, signal });
			if (disposed || ticket !== epoch) return;
			setFeedback(
				accepted
					? { value: { phase: 'idle', message: '' } }
					: {
							value: {
								phase: previousPhase === 'confirmed' ? 'confirmed' : 'failed',
								message: '页面未能打开，原业务结果不受影响。请重新导航。'
							},
							key: 'app.templates.results.thePageDidNotOpenTheOriginalBusinessResult'
						}
			);
		} catch (error) {
			if (!disposed && ticket === epoch) {
				setFeedback({
					value: {
						phase: previousPhase === 'confirmed' ? 'confirmed' : 'failed',
						message: '导航失败，原业务结果不受影响。请重新导航。'
					},
					key: 'app.templates.results.navigationFailedTheOriginalBusinessResultIsUnchangedTry'
				});
				throw error;
			}
		}
	}
	return {
		feedback: readonly(feedback),
		formatMessage: (scope: AsamI18n) =>
			scope.enabled.value && feedbackKey.value
				? templateText(scope, feedbackKey.value)
				: feedback.value.message,
		replace,
		recover,
		go,
		dispose() {
			if (!disposed) {
				disposed = true;
				invalidate();
			}
		}
	};
}

.result-page {
	--result-paper: var(--asam-color-surface-page);
	--result-surface: var(--asam-color-surface, #fff);
	--result-text: var(--asam-color-text-primary, #252a2c);
	--result-muted: var(--asam-color-text-regular, #434343);
	--result-line: var(--asam-color-border, #d9dedf);
	--result-accent: var(--asam-semantic-primary-foreground);
	--result-wash: var(--asam-color-surface-muted);
	--result-brand-bg: var(--asam-semantic-primary-soft);
	--result-brand-text: var(--asam-semantic-primary-foreground);
	--result-tech-canvas: var(--asam-color-surface-muted);
	--result-height: var(--asam-density-default-height, 32px);
	display: flex;
	flex-direction: column;
	min-height: calc(100dvh - 64px);
	box-sizing: border-box;
	background: var(--result-paper);
	color: var(--result-text);
	font-family: var(--asam-typography-font-family);
	line-height: 1.6;
	overflow-wrap: anywhere;
}
.result-page[data-theme='dark'] {
	color-scheme: dark;
}
.result-page[data-size='large'] {
	--result-height: var(--asam-density-large-height, 40px);
}
.result-page[data-size='big'] {
	--result-height: var(--asam-density-big-height, 36px);
}
.result-page[data-size='small'] {
	--result-height: var(--asam-density-small-height, 28px);
}
.result-wordmark {
	font-size: 14px;
	font-weight: 650;
	letter-spacing: 0.04em;
}
.result-page .el-result {
	padding: 0;
	align-items: stretch;
	text-align: left;
}
.result-page .el-result__title {
	margin: 0;
}
.result-page .el-result__title p {
	font-size: clamp(26px, 3.2vw, 42px);
	font-weight: 600;
	line-height: 1.3;
	letter-spacing: -0.03em;
	color: var(--result-text);
}
.result-page .el-result__subtitle {
	margin-top: 20px;
}
.result-page .el-result__subtitle p {
	color: var(--result-muted);
	line-height: 1.8;
	max-width: 50ch;
}
.result-page .el-result__extra {
	margin-top: 24px;
	text-align: left;
}
.result-page .asam-state-panel-actions {
	justify-content: flex-start;
	gap: 12px;
}
.result-page .asam-state-panel button:not([class*='el-']) {
	min-height: var(--result-height);
	padding: 0 18px;
	border-color: var(--result-line);
	color: var(--result-text);
	background: var(--result-surface);
	border-radius: var(--asam-radius-control, 6px);
}
.result-page .asam-state-panel button:not([class*='el-']):first-child {
	background: var(--asam-semantic-primary-solid);
	color: var(--asam-semantic-primary-on-solid);
	border-color: var(--asam-semantic-primary-solid);
}
.result-page .asam-state-panel button:not([class*='el-']):focus-visible {
	outline: 3px solid var(--asam-semantic-focus);
	outline-offset: 4px;
}
.result-page .asam-state-panel button:not([class*='el-']):active {
	transform: scale(0.98);
}
.result-details {
	color: var(--result-muted);
	font-size: 13px;
	max-width: 65ch;
}
.result-details p {
	margin: 0 0 16px;
}
.result-path bdi {
	display: block;
	font-family: Consolas, monospace;
}
.result-feedback {
	min-height: 24px;
	color: var(--result-text);
}
.result-sr {
	position: absolute;
	width: 1px;
	height: 1px;
	clip-path: inset(50%);
	overflow: hidden;
}
@media (prefers-reduced-motion: no-preference) {
	.result-content {
		animation: result-enter 220ms cubic-bezier(0.16, 1, 0.3, 1);
	}
	.result-page button:not([class*='el-']) {
		transition: transform 140ms cubic-bezier(0.16, 1, 0.3, 1);
	}
}
@keyframes result-enter {
	from {
		transform: translateY(6px);
	}
	to {
		transform: translateY(0);
	}
}
@media (max-width: 767px) {
	.result-page .el-result__title p {
		font-size: 28px;
	}
	.result-page .asam-state-panel-actions {
		gap: 10px;
	}
}

import type { AsamI18n } from '@asam-ui/ui/i18n';
import type { Ref } from 'vue';
import type { AsamControlSize } from '@asam-ui/ui';

export type ResultKind = 'success' | 'failure' | 'forbidden' | 'not-found' | 'server-error';
export type ResultFamily = 'minimal' | 'brand' | 'tech';
export interface ResultIdentity {
	id: string;
	/** 当前宿主路由完整路径。 */
	route: string;
	owner: string;
	scope: string;
	/** 同一结果被替换时递增。 */
	revision: number;
}
export type ResultInput = ResultIdentity & {
	title?: string;
	description?: string;
	/** 只允许公开关联 ID，禁止传入凭据或堆栈。 */
	correlationId?: string;
	returnTarget?: string;
	nextTarget?: string;
	disabled?: boolean;
	readonly?: boolean;
} & (
		| { kind: 'success'; confirmed: true }
		| { kind: 'failure' | 'server-error'; writeState: 'unknown' | 'failed' }
		| { kind: 'forbidden' }
		| { kind: 'not-found'; unknownPath: string }
	);
export type RecoveryOutcome =
	| { status: 'confirmed'; message?: string }
	| { status: 'still-failed'; message?: string }
	| { status: 'denied' };
export interface ReadRecovery {
	/** 此契约只允许读取或核实，不能用来重发业务写入。 */
	operation: 'read' | 'verify';
	run: (
		context: Readonly<ResultInput> & { signal: AbortSignal }
	) => RecoveryOutcome | Promise<RecoveryOutcome>;
}
export interface ResultHost {
	/** key 到目标的映射由宿主显式定义，并由 032 navigation 处理。 */
	allows: (target: string) => boolean;
	/** 延迟实际导航的宿主必须在副作用前核对 signal 与此固定身份。 */
	navigate: (
		target: string,
		context: Readonly<ResultInput> & { signal: AbortSignal }
	) => boolean | Promise<boolean>;
	fallback: string;
	recovery?: ReadRecovery;
}
export interface ResultPageProps {
	/** 仅展示层覆盖，不改变原动作或结果状态。 */
	tone?: 'success' | 'error' | 'warning' | 'info';
	/** 显示公共状态组件原生图标；默认保留旧简约页的代码标记。 */
	nativeIcon?: boolean;
	actionLabels?: Readonly<Record<string, string>>;
	/** 将已有具名动作按公共按钮主色呈现，不新增或替换动作。 */
	primaryAction?: string;
	/** 简约回执可接入内容区预览；未提供时保持原浏览器打印行为。 */
	printReceipt?: (context: Readonly<ResultInput>) => void | Promise<void>;
	input: ResultInput;
	host: ResultHost;
	size?: AsamControlSize;
	theme?: 'light' | 'dark';
}
/** 原样转发 030 的动作协议；success 表示动作完成，不等同于业务恢复。 */
export interface ResultPageEmits {
	start: [id: string];
	success: [id: string];
	failure: [id: string, error: unknown];
}
export interface ResultPageEmitter {
	(event: 'start', id: string): void;
	(event: 'success', id: string): void;
	(event: 'failure', id: string, error: unknown): void;
}
export interface ResultFeedback {
	phase: 'idle' | 'busy' | 'confirmed' | 'failed' | 'denied';
	message: string;
}
export interface ResultController<TInput extends ResultInput = ResultInput> {
	feedback: Readonly<Ref<ResultFeedback>>;
	formatMessage?: (scope: AsamI18n) => string;
	replace: (input: TInput, host?: ResultHost) => void;
	recover: () => Promise<void>;
	go: (intent: 'return' | 'next') => Promise<void>;
	dispose: () => void;
}

import { receiptKey, validateReceiptFields, freezeReceipt } from '../success/Data.js';
import type { ResultIdentity } from '../Types.js';
import type { FailureSnapshot } from './Types.js';
export function decodeFailure(
	snapshot: FailureSnapshot,
	identity: ResultIdentity
): FailureSnapshot {
	if (
		!snapshot ||
		snapshot.input?.kind !== 'failure' ||
		!['failed', 'unknown'].includes(snapshot.input.writeState) ||
		receiptKey(snapshot.input) !== receiptKey(identity)
	)
		throw Error('Invalid failure receipt');
	for (const name of ['title', 'description', 'correlationId', 'returnTarget', 'nextTarget'])
		if (
			Reflect.get(snapshot.input, name) !== undefined &&
			typeof Reflect.get(snapshot.input, name) !== 'string'
		)
			throw Error('Invalid result text');
	for (const name of ['disabled', 'readonly'])
		if (
			Reflect.get(snapshot.input, name) !== undefined &&
			typeof Reflect.get(snapshot.input, name) !== 'boolean'
		)
			throw Error('Invalid result policy');
	validateReceiptFields(snapshot.receipt, identity);
	if (!Array.isArray(snapshot.reasons)) throw Error('Failure reasons missing');
	if (
		snapshot.input.writeState === 'failed' &&
		(snapshot.reasons.length !== 2 ||
			new Set(snapshot.reasons.map((reason) => reason.id)).size !== 2)
	)
		throw Error('Two distinct failure reasons required');
	for (const reason of snapshot.reasons)
		if (
			!['purpose', 'project'].includes(reason.id) ||
			(reason.target !== undefined &&
				reason.target !== (reason.id === 'purpose' ? 'draft-purpose' : 'draft-project')) ||
			typeof reason.title !== 'string' ||
			typeof reason.description !== 'string'
		)
			throw Error('Invalid reason target');
	const copy = structuredClone({
		...snapshot,
		reasons: snapshot.input.writeState === 'unknown' ? [] : snapshot.reasons
	});
	return freezeReceipt(copy);
}

import { computed, reactive, shallowRef, watch, nextTick } from 'vue';
import type { Component } from 'vue';
import { createRouter, createMemoryHistory } from 'vue-router';
import { createNavigation } from '../navigation/Navigation.js';
import { receiptKey } from '../success/Data.js';
import type { ResultHost, ResultIdentity, ResultInput } from '../Types.js';
import type { ReceiptReadRequest } from '../success/Types.js';
import type { FailureReadHost, FailureSnapshot } from './Types.js';
/** 仅本地合成adapter。真实导航仍由原032模块负责，没有业务提交服务。 */
export function createFailureFixture(
	locale: () => string,
	components: { scene: Component; destination: Component }
) {
	const controls = reactive({
		owner: 'reader-a',
		scope: 'synthetic-east',
		revision: 1,
		mode: 'failed' as
			'failed' | 'unknown' | 'empty' | 'error' | 'timeout' | 'partial' | 'zero' | 'long',
		delayMs: 80,
		verification: 'unknown' as
			'unknown' | 'failed' | 'confirmed' | 'denied' | 'error' | 'late' | 'timeout',
		navigation: 'normal' as 'normal' | 'cancel' | 'error',
		readonly: false,
		disabled: false,
		denied: false,
		invalidId: false
	});
	const audit = reactive({
		reads: 0,
		verifications: 0,
		navigations: 0,
		aborted: 0,
		writes: 0,
		localEdits: 0,
		readerVersion: 1,
		actions: 0
	});
	const draft = reactive({ purpose: '', project: '' }),
		lastSnapshot = shallowRef<FailureSnapshot>(),
		destination = shallowRef<FailureSnapshot>(),
		initialized = shallowRef(false);
	let disposed = false,
		navEpoch = 0,
		activeNavigation:
			| { ticket: number; context: Readonly<ResultInput> & { signal: AbortSignal } }
			| undefined;
	const timers = new Set<() => void>();
	const identity = computed<ResultIdentity>(() => ({
		id: controls.invalidId ? '' : 'synthetic-receipt-018',
		route: '/result/fail',
		owner: controls.owner,
		scope: controls.scope,
		revision: controls.revision
	}));
	const matches = (who: ResultIdentity) => {
		try {
			return !disposed && !controls.denied && receiptKey(who) === receiptKey(identity.value);
		} catch {
			return false;
		}
	};
	function wait(signal: AbortSignal, ms: number) {
		return new Promise<void>((resolve, reject) => {
			let done = false;
			const finish = (abort: boolean) => {
				if (done) return;
				done = true;
				clearTimeout(timer);
				signal.removeEventListener('abort', stop);
				timers.delete(stop);
				if (abort) {
					audit.aborted++;
					reject(new DOMException('Aborted', 'AbortError'));
				} else resolve();
			};
			const stop = () => finish(true),
				timer = setTimeout(() => finish(false), ms);
			timers.add(stop);
			if (signal.aborted || disposed) stop();
			else signal.addEventListener('abort', stop, { once: true });
		});
	}
	const router = createRouter({
		history: createMemoryHistory(),
		routes: [
			{ path: '/', redirect: '/result/fail' },
			{ path: '/result/fail', component: components.scene }
		]
	});
	const targetPaths = {
		workspace: '/local/workspace',
		draft: '/local/draft',
		'draft-purpose': '/local/draft/purpose',
		'draft-project': '/local/draft/project'
	};
	const navigation = createNavigation({
		router,
		scope: 'synthetic-failure-navigation',
		fallback: '/result/fail',
		components: { draft: components.destination },
		load: async () =>
			controls.denied
				? []
				: Object.entries(targetPaths).map(([id, path]) => ({
						id,
						path,
						title: id,
						resource: 'draft',
						cache: false
					})),
		confirm: async () => {
			const own = activeNavigation;
			await nextTick();
			return (
				!own ||
				(!own.context.signal.aborted &&
					own.ticket === navEpoch &&
					matches(own.context) &&
					!controls.readonly &&
					!controls.disabled &&
					controls.navigation !== 'cancel')
			);
		}
	});
	const services = shallowRef<FailureReadHost['services']>();
	function makeServices(): FailureReadHost['services'] {
		return {
			async read(request: ReceiptReadRequest) {
				audit.reads++;
				const mode = controls.mode,
					t = (zh: string, en: string) => (request.locale === 'en' ? en : zh);
				await wait(request.signal, mode === 'timeout' ? 2000 : controls.delayMs);
				if (!request.isCurrent() || !matches(request))
					throw new DOMException('Aborted', 'AbortError');
				if (mode === 'error') throw Error('PRIVATE_FAILURE_READ_ERROR');
				if (mode === 'empty') return { status: 'empty' };
				const who = {
					id: request.id,
					route: request.route,
					owner: request.owner,
					scope: request.scope,
					revision: request.revision
				};
				const unknown = mode === 'unknown';
				const snapshot: FailureSnapshot = {
					input: {
						...who,
						kind: 'failure',
						writeState: unknown ? 'unknown' : 'failed',
						title: unknown
							? t('提交结果待确认', 'Submission result unconfirmed')
							: t('提交未完成', 'Submission incomplete'),
						description: unknown
							? t(
									'响应尚未确认，请先核实原操作结果；没有重新提交。',
									'The response is unconfirmed. Verify the original operation; nothing has been resubmitted.'
								)
							: t(
									'请处理下列问题，再继续完成申请。本例未连接真实提交服务。',
									'Review these issues before continuing. This demo has no live submission service.'
								),
						returnTarget: 'draft'
					},
					receipt: {
						identity: who,
						subject:
							mode === 'long'
								? t(
										'研发测试设备采购及多团队长周期测试环境能力扩展项目',
										'Development testing equipment purchase and multi-team long-term environment expansion'
									)
								: t('研发测试设备采购', 'Development test equipment purchase'),
						number: 'SQ-20261030-018',
						applicant:
							who.owner === 'reader-a'
								? t('林岚', 'Lin Lan')
								: t('周远', 'Zhou Yuan'),
						amountCents: mode === 'partial' ? null : mode === 'zero' ? 0 : 2468000,
						provenance: 'synthetic'
					},
					reasons: unknown
						? []
						: [
								{
									id: 'purpose',
									title: t('请补充采购用途说明', 'Add the purchase purpose'),
									description: t(
										'说明设备使用场景，便于审批人判断。',
										'Describe the intended usage so the reviewer can assess the request.'
									),
									target: 'draft-purpose'
								},
								{
									id: 'project',
									title: t('请确认关联项目', 'Confirm the related project'),
									description: t(
										mode === 'long'
											? '关联项目暂不可修改。请保留当前草稿，向项目负责人核对申请归属与费用分摊，并等待项目资料恢复后再继续填写。'
											: '项目归属决定后续费用分摊。',
										mode === 'long'
